insert into storage.buckets(id,name,public) values('books','books',true) on conflict(id) do update set public=true; insert into storage.buckets(id,name,public) values('covers','covers',true) on conflict(id) do update set public=true;
drop policy if exists "Public read books files" on storage.objects; create policy "Public read books files" on storage.objects for select to public using(bucket_id='books'); drop policy if exists "Public read covers files" on storage.objects; create policy "Public read covers files" on storage.objects for select to public using(bucket_id='covers');
drop policy if exists "Admin upload books" on storage.objects; create policy "Admin upload books" on storage.objects for insert to authenticated with check(bucket_id='books'); drop policy if exists "Admin upload covers" on storage.objects; create policy "Admin upload covers" on storage.objects for insert to authenticated with check(bucket_id='covers');
drop policy if exists "Admin update books" on storage.objects; create policy "Admin update books" on storage.objects for update to authenticated using(bucket_id='books') with check(bucket_id='books'); drop policy if exists "Admin update covers" on storage.objects; create policy "Admin update covers" on storage.objects for update to authenticated using(bucket_id='covers') with check(bucket_id='covers');
drop policy if exists "Admin delete books" on storage.objects; create policy "Admin delete books" on storage.objects for delete to authenticated using(bucket_id='books'); drop policy if exists "Admin delete covers" on storage.objects; create policy "Admin delete covers" on storage.objects for delete to authenticated using(bucket_id='covers');
update public.books set category=null where trim(coalesce(category,''))='عاشقانه';
